package com.sage.business.code.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.*;
import java.util.*;
import org.junit.*;
/** A READY candidate remains immutable across a real profile handoff; old epoch cannot adopt it. */
public class WritableHandoffProtocolTest extends WritableCollaborationProtocolTest {
 private boolean handoffScenario,done;private String profileRevision;private final List<JsonNode> requests=new java.util.concurrent.CopyOnWriteArrayList<>();
 private static final class ScenarioCompleted extends RuntimeException{}
 @Override protected boolean deleteFixtureRoot(){return done||super.deleteFixtureRoot();}
 @Override protected void configureCollaboration(ServiceConfig config){super.configureCollaboration(config);config.collaborationHandoffEnabled=true;try{Path directory=config.getAgentProfilesDirectory();Files.createDirectories(directory);mapper.writeValue(directory.resolve("reviewer.json").toFile(),mapper.createObjectNode().put("schemaVersion","agent-profile/1.1").put("id","reviewer").put("name","Reviewer").put("description","Same native tools, independently pinned instructions").put("instructions","TARGET_PROFILE_REVIEWER: retain the original task and only explicitly adopt authorized candidates."));profileRevision=com.sage.business.code.application.session.AgentProfileCatalog.load(directory,mapper).resolve("reviewer").getRevision();}catch(Exception failure){throw new IllegalStateException(failure);}}
 @Override protected void observeModelRequest(JsonNode request){super.observeModelRequest(request);requests.add(request);}
 @Test public void readyCandidateRequiresExplicitNewEpochGrantAfterActualProfileHandoff()throws Exception{handoffScenario=true;try{exercise(false,false);Assert.fail("Scenario hook not reached");}catch(ScenarioCompleted completed){Assert.assertTrue(done);}}
 @Override protected void beforeWritableAdoption(String rid,String sid)throws Exception{
  if(!handoffScenario)return;String group="/api/v2/runs/"+rid+"/collaboration-groups/group-one";JsonNode ready=api("GET",group,null,b,null,200),candidate=ready.path("candidates").get(0),oldSources=ready.path("authorization").path("sources"),budget=ready.path("sharedBudget");Assert.assertEquals(2,parentCallCount());
  ObjectNode transition=mapper.createObjectNode().put("transitionId","ready-handoff");transition.putObject("target").put("agentProfileId","reviewer").put("agentProfileRevision",profileRevision);JsonNode preflight=api("POST","/api/v2/runs/"+rid+"/assignment-transitions/preflight",null,b,transition,200);transition.put("preflightDigest",preflight.path("preflightDigest").asText()).put("expectedExecutionEpoch","1").put("expectedRunStateVersion",preflight.path("runStateVersion").asText()).put("expectedModelSettingsRevision",preflight.path("modelSettingsRevision").asText());api("POST","/api/v2/runs/"+rid+"/assignment-transitions","ready-handoff",b,transition,202);
  await(()->"PAUSE_REQUESTED".equals(api("GET","/api/v2/runs/"+rid,null,b,null,200).path("controlState").asText()),"Handoff did not request actual main pause");releaseModel.release();await(()->"ACTIVE".equals(api("GET","/api/v2/runs/"+rid+"/assignment-transitions/ready-handoff",null,b,null,200).path("state").asText()),"Target Product did not start");await(()->parentCallCount()==3,"Target profile did not issue its actual semantic model request");Assert.assertTrue(requests.stream().anyMatch(request->request.toString().contains("TARGET_PROFILE_REVIEWER")));
  JsonNode originalPreview=api("GET",group,null,b,null,200).path("previews").get(0),originalSelection=api("GET",group,null,b,null,200).path("selections").get(0),run=api("GET","/api/v2/runs/"+rid,null,b,null,200);ObjectNode stale=mapper.createObjectNode().put("adoptionId","old-epoch-adopt").put("expectedRunStateVersion",run.path("stateVersion").asText()).put("expectedExecutionEpoch","1").put("selectionId",originalSelection.path("entityId").asText()).put("selectionFingerprint",originalSelection.path("selectionFingerprint").asText()).put("previewId",originalPreview.path("entityId").asText()).put("previewFingerprint",originalPreview.path("previewFingerprint").asText()).put("mode","STRICT");Assert.assertEquals("EXECUTION_EPOCH_CONFLICT",api("POST",group+"/adoptions","old-epoch-adopt",a,stale,409).path("code").asText());
  ready=api("GET",group,null,b,null,200);ObjectNode grant=mapper.createObjectNode().put("requestId","epoch-two-grant").put("expectedGraphRevision",ready.path("revision").asText()).put("expectedExecutionEpoch","2").put("graphFingerprint",ready.path("graphFingerprint").asText()).put("adoptionMode","USER_CONFIRM").put("retryLimit",0).put("repairLimit",0);grant.set("integrationReserve",mapper.createObjectNode().put("logicalCalls","1").put("httpRequests","1").put("editAttempts","1"));grant.set("repairReserve",mapper.createObjectNode().put("logicalCalls","0").put("httpRequests","0").put("editAttempts","0"));ObjectNode unit=grant.putArray("units").addObject().put("unitId","unit-one");ObjectNode allowance=mapper.createObjectNode().put("logicalCalls","4").put("httpRequests","4").put("editAttempts","2");unit.set("total",allowance);unit.set("perAttempt",allowance.deepCopy());api("POST",group+"/authorizations","epoch-two-grant",a,grant,202);ready=api("GET",group,null,b,null,200);Assert.assertEquals(oldSources,ready.path("authorization").path("sources"));for(String dimension:Arrays.asList("LOGICAL_CALL","HTTP_REQUEST","EDIT_ATTEMPT"))Assert.assertTrue(ready.path("sharedBudget").path(dimension).path("spent").asLong()>=budget.path(dimension).path("spent").asLong());
  ObjectNode selection=mapper.createObjectNode().put("selectionId","epoch-two-selection").put("expectedGraphRevision",ready.path("revision").asText());selection.putArray("units").addObject().put("unitId","unit-one").put("candidateId",candidate.path("entityId").asText()).put("candidateFingerprint",candidate.path("candidateFingerprint").asText());JsonNode selected=api("POST",group+"/selections","epoch-two-selection",a,selection,202);ObjectNode preview=mapper.createObjectNode().put("previewId","epoch-two-preview").put("selectionFingerprint",selected.path("selectionFingerprint").asText()).put("mode","STRICT");JsonNode prepared=api("POST",group+"/selections/epoch-two-selection/previews","epoch-two-preview",a,preview,202);run=api("GET","/api/v2/runs/"+rid,null,b,null,200);ObjectNode adopt=stale.deepCopy().put("adoptionId","epoch-two-adopt").put("expectedExecutionEpoch","2").put("expectedRunStateVersion",run.path("stateVersion").asText()).put("selectionId","epoch-two-selection").put("selectionFingerprint",selected.path("selectionFingerprint").asText()).put("previewId","epoch-two-preview").put("previewFingerprint",prepared.path("previewFingerprint").asText());api("POST",group+"/adoptions","epoch-two-adopt",a,adopt,202);releaseModel.release();await(()->"ADOPTED".equals(api("GET",group+"/adoptions/epoch-two-adopt",null,b,null,200).path("state").asText()),"New epoch did not adopt original fixed candidate");await(()->parentCallCount()==4,"Target main did not continue from adopted V6");releaseModel.release();await(()->"COMPLETED".equals(api("GET","/api/v2/runs/"+rid,null,b,null,200).path("state").asText()),"Target main did not finish same Run");Assert.assertEquals(candidate.path("candidateFingerprint"),api("GET",group,null,b,null,200).path("candidates").get(0).path("candidateFingerprint"));done=true;throw new ScenarioCompleted();
 }
}
